23	/**
24	 * Normalizes a submitted telephone number into the canonical form that is stored for an owner and
25	 * compared when detecting duplicate telephones. Kept apart from {@link OwnerRestControllerV1} so the
26	 * request handler stays focused on orchestration while the rules for what makes a telephone
27	 * acceptable, and how it is canonicalized, live in one place.
28	 *
29	 * <p>The rule canonicalizes to E.164: spaces, dashes and brackets are stripped; a leading '+' with a
30	 * country code is kept as-is, otherwise country code '+61' is assumed and a single leading '0' is
31	 * dropped from the national digits. The result must be a '+' followed by 8 to 15 digits. That '+' and
32	 * digit string is what gets stored and returned.
33	 */
34	final class TelephoneNormalizer {
35	
36	    private TelephoneNormalizer() {
37	    }
38	
39	    /**
40	     * Normalizes a raw telephone value for owner creation into E.164 form. The normalized value is both
41	     * what gets stored and what duplicate detection compares against, so two inputs that canonicalize to
42	     * the same value are treated as the same telephone.
43	     *
44	     * <p>Spaces, dashes and brackets are removed. A value beginning with '+' keeps its leading '+' and
45	     * country code; any other value assumes country code '+61' and drops a single leading '0' from the
46	     * national digits. The result must be a '+' followed by 8 to 15 digits.
47	     *
48	     * @param telephone the raw telephone value submitted by the client
49	     * @return the normalized E.164 telephone number (a '+' followed by 8 to 15 digits)
50	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
51	     */
52	    static String normalize(String telephone) {
53	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]{}]", "");
54	
55	        String e164;
56	        if (cleaned.startsWith("+")) {
57	            e164 = "+" + cleaned.substring(1);
58	        }
59	        else {
60	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
61	            e164 = "+61" + national;
62	        }
63	
64	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
65	            throw new InvalidOwnerFieldsException(List.of("telephone"));
66	        }
67	        return e164;
68	    }
69	
70	}
